extra_methods.body:
_hologramText = text;
_dialogueState = index;
if (GameContext.Instance != null)
{
    var dialogueSys = GameContext.Instance.Get<DialogueSystem>();
    if (dialogueSys != null)
        dialogueSys.StartDialogue();
}

scripts.update_extra:
if (_timeOfDay > _nightThreshold) _blueFactor = Mathf.Lerp(1f, 0.2f, _timeOfDay); else _blueFactor = Mathf.Lerp(0.2f, 1f, _timeOfDay - _nightThreshold);

if (_lightSource != null) {
    var r = (byte)(255 * _blueFactor);
    var g = (byte)(255 * _blueFactor);
    var b = (byte)(255 * _blueFactor);
    _lightSource.color = new Color32(r, g, b, 255u) * _lightSource.intensity;
}

if (_timeOfDay < 0.1f || _timeOfDay > 0.9f) {
    var audioMgr = GameContext.Instance.Get<AudioDirectorAudioManager>();
    if (audioMgr != null) audioMgr.Play("ambient_rain_heavy", default);
}

scripts.fixed_update_extra:
if (_rb == null) _rb = GetComponent<Rigidbody>();

if (GameContext.Instance.Get<PlayerController>().CurrentMode != PlayerController.ModeVehicleCar) return;

// Apply vertical lift for hover effect
float lift = _liftForce * Time.fixedDeltaTime;
_rb.AddForce(Vector3.up * lift, ForceMode.Impulse);

// Apply forward thrust based on throttle input
if (Input.GetAxis("Throttle") > 0f)
{
    Vector3 thrust = _thrusterForce.normalized * Input.GetAxis("Throttle");
    _rb.AddForce(thrust, ForceMode.Impulse);
}

extra_methods.body:
if (_isSaving) return;
_isSaving = true;
var data = new SaveSystemData();
data.CurrentTime = Time.time;
data.PlayerHealth.CurrentHealth = GameContext.Instance.Get<PlayerHealth>().CurrentHealth;
data.PlayerHealth.MaxHealth = GameContext.Instance.Get<PlayerHealth>().MaxHealth;
data.PlayerInventory.Stacks = GameContext.Instance.Get<PlayerInventory>().Stacks;
data.GameRules.Finished = GameContext.Instance.Get<GameRules>().Finished;
data.SceneTransition.CurrentSceneName = SceneManager.GetActiveScene().name;
File.WriteAllText(_savePath, JsonUtility.ToJson(data));
Debug.Log("Game Saved.");
_isSaving = false;

if (!System.IO.File.Exists(_savePath)) return false;
var json = System.IO.File.ReadAllText(_savePath);
var data = JsonUtility.FromJson<SaveSystemData>(json);
if (data == null) return false;
// Restore logic would go here based on project architecture
Debug.Log("Game Loaded.");
return true;

if (System.IO.File.Exists(_savePath)) {
System.IO.File.Delete(_savePath);
Debug.Log("Save deleted.");
}
else {
Debug.LogWarning("No save file to delete.");
}

Vector3 start = transform.position + new Vector3(0f, -_tunnelWidth / 2f, 0f);
Vector3 end = transform.position + new Vector3(_tunnelWidth * _segmentCount, -_tunnelWidth / 2f, 0f);
for (int i = 0; i < _segmentCount; i++)
{
    float t = (float)i / (float)_segmentCount;
    Vector3 center = Mathf.Lerp(start, end, t) + new Vector3(0f, -_tunnelWidth * (Mathf.Sin(t * Mathf.PI) * 0.5f), 0f);
    Instantiate(_meshFilter.gameObject, center, Quaternion.identity, transform);
}

Vector3 start = transform.position + new Vector3(0f, _rooftopHeight * 2f, 0f);
Vector3 end = transform.position + new Vector3(_tunnelWidth * _segmentCount, _rooftopHeight * 2f, 0f);
for (int i = 0; i < _segmentCount; i++)
{
    float t = (float)i / (float)_segmentCount;
    Vector3 center = Mathf.Lerp(start, end, t) + new Vector3(0f, _rooftopHeight * (Mathf.Cos(t * Mathf.PI) * 0.5f), 0f);
    Instantiate(_meshFilter.gameObject, center, Quaternion.identity, transform);
}

input.update_extra:
if (_cooldown > 0f) _cooldown -= Time.deltaTime;

if (_isHoverbike && _rigidbody != null)
{
    if (Input.GetButtonDown("Jump"))
    {
        _rigidbody.AddForce(Vector3.up * _hoverLiftForce, ForceMode.Impulse);
        _cooldown = 0.5f;
    }
}

if (_isHoverbike && _rigidbody != null)
{
    if (Input.GetButton("Jump"))
    {
        _rigidbody.AddForce(Vector3.up * _hoverLiftForce * Time.deltaTime, ForceMode.Force);
    }
}

extra_methods.body:
_isHoverbike = enabled;
if (_rigidbody != null)
{
    if (enabled) _rigidbody.useGravity = false;
    else _rigidbody.useGravity = true;
}

if (tag != null && !string.IsNullOrEmpty(tag))
{
    // Notify District Manager for ambient audio/sky shifts
    if (_districtTag == "Building" || _districtTag == "Environment")
        OnActivated?.Invoke();
}

if (_patrolPointIndex < 0 || _patrolPoints.Count == 0) return;

Vector3 target = _patrolPoints[_patrolPointIndex];
float distance = Vector3.Distance(transform.position, target);

if (distance > 2f)
{
    transform.LookAt(target);
}
else if (distance < 1f)
{
    _patrolPointIndex = (_patrolPointIndex + 1) % _patrolPoints.Count;
}
